```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

#define BOARD_WIDTH 800
#define BOARD_HEIGHT 600

// Game board struct
typedef struct {
    SDL_Window *window;
    SDL_Renderer *renderer;
    SDL_Surface *background;
    SDL_Color palette[4];
    int tiles_per_side;
    int tile_width;
    int tile_height;
} Board;

// Snake struct
typedef struct {
    int x, y;
    int dir_x, dir_y;
    int speed;
    SDL_Texture *head;
    SDL_Texture **segments;
    int num_segments;
} Snake;

// Food struct
typedef struct {
    int x, y;
    SDL_Texture *texture;
} Food;

// Function prototypes
Board *create_board();
void destroy_board(Board *board);
void draw_board(Board *board);
void draw_snake(Board *board, Snake *snake);
void draw_food(Board *board, Food *food);
void move_snake(Snake *snake, Board *board);
void place_food(Board *board, Food *food);
int is_out_of_bounds(int x, int y, Board *board);
int collides_with_snake(int x, int y, Snake *snake);
void update_score(int *score, int increment);
void play_sound_effect(SDL_Mixer_Chunk *chunk);

int main(int argc, char *argv[]) {
    SDL_Event event;
    Board *board = create_board();
    Snake *snake = malloc(sizeof(Snake));
    Food *food = malloc(sizeof(Food));
    int score = 0;

    // Load images
    SDL_Surface *head_surface = IMG_Load("head.png");
    SDL_Surface *segment_surface = IMG_Load("segment.png");
    SDL_Surface *food_surface = IMG_Load("food.png");

    // Convert surfaces to textures
    SDL_Texture *head_texture = SDL_CreateTextureFromSurface(board->renderer, head_surface);
    SDL_Texture *segment_texture = SDL_CreateTextureFromSurface(board->renderer, segment_surface);
    SDL_Texture *food_texture = SDL_CreateTextureFromSurface(board->renderer, food_surface);

    // Initialize snake
    snake->x = BOARD_WIDTH / 2;
    snake->y = BOARD_HEIGHT / 2;
    snake->dir_x = 0;
    snake->dir_y = -1;
    snake->speed = 5;
    snake->head = head_texture;
    snake->segments = malloc(sizeof(SDL_Texture *));
    snake->num_segments = 1;

    // Initialize food
    place_food(board, food);

    // Main game loop
    while (1) {
        // Handle events
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_LEFT:
                        if (snake->dir_y != 0) {
                            snake->dir_x = -1;
                            snake->dir_y = 0;
                        }
                        break;
                    case SDLK_RIGHT:
                        if (snake->dir_y != 0) {
                            snake->dir_x = 1;
                            snake->dir_y = 0;
                        }
                        break;
                    case SDLK_UP:
                        if (snake->dir_x != 0) {
                            snake->dir_x = 0;
                            snake->dir_y = -1;
                        }
                        break;
                    case SDLK_DOWN:
                        if (snake->dir_x != 0) {
                            snake->dir_x = 0;
                            snake->dir_y = 1;
                        }
                        break;
                }
            }
        }

        // Move snake
        move_snake(snake, board);

        // Check for collisions
        if (collides_with_snake(snake->x, snake->y, snake) ||
            is_out_of_bounds(snake->x, snake->y, board)) {
            // Game over
            printf("Game over! Score: %d\n", score);
            SDL_Delay(2000);
            break;
        }

        // Check for food collision
        if (snake->x == food->x && snake->y == food->y) {
            // Eat food
            play_sound_effect(NULL); // TODO: Load sound effect
            place_food(board, food);
            update_score(&score, 10);
            snake->num_segments++;
            SDL_Texture **new_segments = malloc((snake->num_segments + 1) * sizeof(SDL_Texture *));
            for (int I = 0; I < snake->num_segments - 1; i++) {
                new_segments[i] = snake->segments[i];
            }
            new_segments[snake->num_segments - 1] = segment_texture;
            free(snake->segments);
            snake->segments = new_segments;
        }

        // Draw game elements
        SDL_RenderClear(board->renderer);
        draw_board(board);
        draw_snake(board, snake);
        draw_food(board, food);
        SDL_RenderPresent(board->renderer);

        // Delay for game speed
        SDL_Delay(1000 / snake->speed);
    }

    // Clean up
    SDL_DestroyTexture(head_texture);
    SDL_DestroyTexture(segment_texture);
    SDL_DestroyTexture(food_texture);
    free(snake->segments);
    free(snake);
    free(food);
    destroy_board(board);

    return 0;
}

// Function implementations

Board *create_board() {
    Board *board = malloc(sizeof(Board));

    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL could not initialize! SDL_Error: %s\n", SDL_GetError());
        exit(1);
    }

    if (!(board->window = SDL_CreateWindow("Snake", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, BOARD_WIDTH, BOARD_HEIGHT, SDL_WINDOW_SHOWN))) {
        printf("Window could not be created! SDL_Error: %s\n", SDL_GetError());
        exit(1);
    }

    if (!(board->renderer = SDL_CreateRenderer(board->window, -1, SDL_RENDERER_ACCELERATED))) {
        printf("Renderer could not be created! SDL_Error: %s\n", SDL_GetError());
        exit(1);
    }

    board->background = SDL_LoadBMP("background.bmp");

    board->palette[0] = SDL_MapRGB(board->background->format, 0x00, 0x00, 0x00);
    board->palette[1] = SDL_MapRGB(board->background->format, 0xFF, 0xFF, 0xFF);
    board->palette[2] = SDL_MapRGB(board->background->format, 0x00, 0xFF, 0x00);
    board->palette[3] = SDL_MapRGB(board->background->format, 0xFF, 0x00, 0x00);

    board->tiles_per_side = BOARD_WIDTH / 20;
    board->tile_width = BOARD_WIDTH / board->tiles_per_side;
    board->tile_height = BOARD_HEIGHT / board->tiles_per_side;

    return board;
}

void destroy_board(Board *board) {
    SDL_FreeSurface(board->background);
    SDL_DestroyRenderer(board->renderer);
    SDL_DestroyWindow(board->window);
    SDL_Quit();
    free(board);
}

void draw_board(Board *board) {
    SDL_Rect rect = {0, 0, board->tile_width, board->tile_height};
    SDL_SetRenderDrawColor(board->renderer, board->palette[1].r, board->palette[1].g, board->palette[1].b, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(board->renderer, &rect);
    rect.y += board->tile_height;
    for (int I = 1; I < board->tiles_per_side; i++) {
        SDL_RenderFillRect(board->renderer, &rect);
        rect.y += board->tile_height;
    }
}

void draw_snake(Board *board, Snake *snake) {
    SDL_Rect head_rect = {
        snake->x * board->tile_width,
        snake->y * board->tile_height,
        board->tile_width,
        board->tile_height
    };
    SDL_RenderCopy(board->renderer, snake->head, NULL, &head_rect);

    for (int I = 0; I < snake->num_segments - 1; i++) {
        SDL_Rect segment_rect = {
            (snake->x + I) * board->tile_width,
            snake->y * board->tile_height,
            board->tile_width,
            board->tile_height
        };
        SDL_RenderCopy(board->renderer, snake->segments[i], NULL, &segment_rect);
    }
}

void draw_food(Board *board, Food *food) {
    SDL_Rect food_rect = {
        food->x * board->tile_width,
        food->y * board->tile_height,
        board->tile_width,
        board->tile_height
    };
    SDL_RenderCopy(board->renderer, food->texture, NULL, &food_rect);
}

void move_snake(Snake *snake, Board *board) {
    snake->x += snake->dir_x * board->tile_width;
    snake->y += snake->dir_y * board->tile_height;

    if (snake->num_segments > 1) {
        for (int I = snake->num_segments - 2; I >= 0; i--) {
            snake->segments[i + 1] = snake->segments[i];
            snake->segments[i]->w = board->tile_width;
            snake->segments[i]->h = board->tile_height;
        }
        snake->segments[0]->w = board->tile_width;
        snake->segments[0]->h = board->tile_height;
    }
}

void place_food(Board *board, Food *food) {
    SDL_Rect food_rect = {
        rand() % (board->tiles_per_side - 1) + 1,
        rand() % (board->tiles_per_side - 1) + 1,
        board->tile_width,
        board->tile_height
    };

    while (collides_with_snake(food_rect.x, food_rect.y, snake)) {
        food_rect.x = rand() % (board->tiles_per_side - 1) + 1;
        food_rect.y = rand() % (board->tiles_per_side - 1) + 1;
    }

    food->x = food_rect.x;
    food->y = food_rect.y;

    food->texture = food_texture;
}

int is_out_of_bounds(int x, int y, Board *board) {
    return x < 0 || x >= board->tiles_per_side || y < 0 || y >= board->tiles_per_side;
}

int collides_with_snake(int x, int y, Snake *snake) {
    SDL_Rect snake_rect = {
        snake->x * snake->segments[0]->w,
        snake->y * snake->segments[0]->h,
        snake->segments[0]->w,
        snake->segments[0]->h
    };

    for (int I = 1; I < snake->num_segments; i++) {
        if (SDL_HasIntersection(&snake_rect, (SDL_Rect *)snake->segments[i])) {
            return 1;
        }
    }

    return 0;
}

void update_score(int *score, int increment) {
    *score += increment;
}

void play_sound_effect(SDL_Mixer_Chunk *chunk) {
    SDL_Init(SDL_INIT_AUDIO);
    SDL_Mixer_Init(SDL_MIXER_INIT_OGG);
    SDL_Mixer_OpenAudio(44100, SDL_AUDIO_FMT Signed16, 2, 1024, SDL_MIXER_AUDIO_DEV AUTO);

    if (chunk == NULL) {
        SDL_Mixer_LoadWAV_RW(&chunk, SDL_RWFromFile("eat.wav", "rb"), SDL_TRUE);
    }

    SDL_Mixer_PlayChannel(-1, chunk, 0);

    SDL_Mixer_CloseAudio();
    SDL_Mixer_Quit();
    SDL_Quit();
}
```

